import { esc, seconds } from './ui.js';
export function bellTimeline(bells, duration) {
    if (!bells || !Number.isFinite(duration) || duration <= 0)
        return '';
    const accepted = bells.windows.filter(w => w.accepted).length;
    return `<section class="panel bell-analysis"><div class="section-heading compact"><div><h3>Klokker gennem hele optagelsen</h3><p>${accepted} af ${bells.windows.length} analysevinduer med klokkeindikation · ${bells.events.length} anslagsforslag</p></div></div><p class="small-print">Anslagsforslag er ændringer i resonanserne. Ekko, svingende klokker og samtidige slag kan give flere forslag for samme slag. Antallet er ikke et antal fysiske klokker.</p>
  <div class="bell-timeline" aria-label="Tidslinje med klokkeindikationer">${bells.windows.map((w, i) => `<button type="button" class="${w.accepted ? 'bell-present' : ''}" data-bell-seek="${w.start}" style="width:${(i === bells.windows.length - 1 ? duration - w.start : 10) / duration * 100}%" title="${seconds(w.start)}–${seconds(w.end)} · ${w.attackCount} anslagsforslag" aria-label="${esc(`Gå til ${seconds(w.start)} · ${w.accepted ? 'Klokkeindikation' : 'Ingen tydelig klokkeindikation'}`)}"></button>`).join('')}</div><div class="bell-time-labels"><span>00:00</span><span>${seconds(duration)}</span></div>
  <details><summary>Se alle analysevinduer og anslagsforslag</summary><p class="small-print">Vinduerne overlapper. Antal forslag pr. vindue må ikke lægges sammen. Klik på et tidspunkt for at gå til det i optagelsen.</p><div class="table-scroll"><table><thead><tr><th>Tidsrum</th><th>Klokkeindikation</th><th>Korte vinduer med resonanser</th><th>Anslagsforslag</th></tr></thead><tbody>${bells.windows.map(w => `<tr><td><button type="button" class="text-button" data-bell-seek="${w.start}">${seconds(w.start)}–${seconds(w.end)}</button></td><td>${w.accepted ? 'Mulig' : 'Utilstrækkelig'}</td><td>${Math.round(w.tonalFraction * 100)}%</td><td>${w.attackCount}</td></tr>`).join('')}</tbody></table></div>
  <h4>Samlede anslagsforslag</h4><div class="bell-event-list">${bells.events.slice(0, 1000).map(e => `<button type="button" class="text-button" data-bell-seek="${e.t}" title="${esc(e.resonancesHz.map(h => Math.round(h) + ' Hz').join(', '))}">${seconds(e.t)}.${Math.floor(e.t % 1 * 10)}</button>`).join('')}</div>${bells.events.length > 1000 ? '<p>De første 1.000 forslag vises her. Den fulde liste findes i lydrapporten.</p>' : ''}<p class="small-print">${bells.warnings.map(esc).join(' ')}</p></details></section>`;
}
